<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class AdmissionController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->canDo('students.manage'),403);}
 public function index(Request $r){$this->ok($r);$q=DB::table('admission_applications as ap')->join('admission_applicants as a','a.id','=','ap.applicant_id')->join('admission_targets as t','t.id','=','ap.target_id')->join('admission_campaigns as c','c.id','=','ap.campaign_id')->join('specialties as sp','sp.id','=','t.specialty_id')->leftJoin('study_groups as g','g.id','=','t.study_group_id')->select('ap.*','a.last_name','a.first_name','a.middle_name','a.birth_date','a.phone','a.email','a.document_number','sp.code as specialty_code','sp.name as specialty','t.education_base','t.planned_places','t.budget_places','t.paid_places','c.name as campaign_name','g.name as group_name');if($r->filled('q')){$s='%'.$r->q.'%';$q->where(fn($x)=>$x->where('a.last_name','like',$s)->orWhere('a.first_name','like',$s)->orWhere('a.document_number','like',$s));}if($r->filled('campaign'))$q->where('ap.campaign_id',$r->integer('campaign'));if($r->filled('target'))$q->where('ap.target_id',$r->integer('target'));if($r->filled('status'))$q->where('ap.status',$r->status);$rows=$q->orderByRaw('COALESCE(ap.entrance_score,ap.average_score) DESC')->orderBy('ap.priority')->orderBy('a.last_name')->paginate(100)->withQueryString();$campaigns=DB::table('admission_campaigns')->orderByDesc('starts_on')->get();$targets=DB::table('admission_targets as t')->join('admission_campaigns as c','c.id','=','t.campaign_id')->join('specialties as sp','sp.id','=','t.specialty_id')->leftJoin('study_groups as g','g.id','=','t.study_group_id')->select('t.*','c.name as campaign_name','sp.code as specialty_code','sp.name as specialty','g.name as group_name')->orderBy('t.specialty')->get();$applicants=DB::table('admission_applicants')->orderBy('last_name')->orderBy('first_name')->get();$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$specialties=DB::table('specialties')->orderBy('code')->get();return view('admission.index',compact('rows','campaigns','targets','applicants','groups','specialties'));}
 public function campaignStore(Request $r){$this->ok($r);$d=$r->validate(['name'=>'required|string|max:255','starts_on'=>'required|date','ends_on'=>'required|date|after_or_equal:starts_on']);DB::table('admission_campaigns')->insert($d+['status'=>'active','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Приёмная кампания создана');}
 public function targetStore(Request $r){$this->ok($r);$d=$r->validate(['campaign_id'=>'required|exists:admission_campaigns,id','specialty_id'=>'required|exists:specialties,id','education_base'=>'nullable|string|max:50','planned_places'=>'required|integer|min:0','budget_places'=>'required|integer|min:0','paid_places'=>'required|integer|min:0','study_group_id'=>'nullable|exists:study_groups,id']);abort_if($d['budget_places']+$d['paid_places']>$d['planned_places'],422,'Бюджетные и платные места не могут превышать общий план.');DB::table('admission_targets')->insert($d+['created_at'=>now(),'updated_at'=>now()]);return back()->with('success','План набора добавлен');}
 public function store(Request $r){$this->ok($r);$d=$r->validate(['last_name'=>'required|string|max:100','first_name'=>'required|string|max:100','middle_name'=>'nullable|string|max:100','birth_date'=>'nullable|date','phone'=>'nullable|string|max:100','email'=>'nullable|email|max:255','document_number'=>'nullable|string|max:100','note'=>'nullable|string|max:5000']);$id=DB::table('admission_applicants')->insertGetId($d+['created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Абитуриент зарегистрирован. Теперь добавьте заявление.')->with('applicant_id',$id);}
 public function applicationStore(Request $r,$applicant){$this->ok($r);abort_unless(DB::table('admission_applicants')->where('id',$applicant)->exists(),404);$d=$r->validate(['target_id'=>'required|exists:admission_targets,id','priority'=>'required|integer|min:1|max:99','average_score'=>'nullable|numeric|min:0|max:5','entrance_score'=>'nullable|numeric|min:0','original_document'=>'nullable|boolean','note'=>'nullable|string|max:5000']);$target=DB::table('admission_targets')->find($d['target_id']);DB::table('admission_applications')->insert($d+['applicant_id'=>$applicant,'campaign_id'=>$target->campaign_id,'original_document'=>$r->boolean('original_document'),'status'=>'submitted','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Заявление добавлено');}
 public function status(Request $r,$application){$this->ok($r);$d=$r->validate(['status'=>'required|in:submitted,verified,recommended,rejected']);DB::table('admission_applications')->where('id',$application)->whereNull('student_id')->update(['status'=>$d['status'],'updated_at'=>now()]);return back()->with('success','Решение сохранено');}
 public function enroll(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');abort_if(!$p,422,'Не выбран учебный период.');PeriodGuard::writable($p->id);$d=$r->validate(['application_ids'=>'required|array|min:1','application_ids.*'=>'integer|exists:admission_applications,id','order_number'=>'required|string|max:100','order_date'=>'required|date','effective_on'=>'required|date','basis'=>'nullable|string|max:5000']);$apps=DB::table('admission_applications as ap')->join('admission_targets as t','t.id','=','ap.target_id')->whereIn('ap.id',$d['application_ids'])->select('ap.*','t.study_group_id')->get();abort_if($apps->contains(fn($x)=>!$x->study_group_id),422,'У плана набора должна быть назначена учебная группа.');DB::transaction(function()use($r,$p,$d,$apps){$order=DB::table('academic_orders')->insertGetId(['academic_period_id'=>$p->id,'number'=>$d['order_number'],'order_date'=>$d['order_date'],'student_id'=>null,'type'=>'enrollment','title'=>'Зачисление по результатам приёмной кампании','basis'=>$d['basis']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);foreach($apps as $ap){if($ap->student_id)continue;$a=DB::table('admission_applicants')->find($ap->applicant_id);$sid=DB::table('students')->insertGetId(['last_name'=>$a->last_name,'first_name'=>$a->first_name,'middle_name'=>$a->middle_name,'current_group_id'=>$ap->study_group_id,'status'=>'active','enrolled_on'=>$d['effective_on'],'created_at'=>now(),'updated_at'=>now()]);DB::table('student_group_memberships')->insert(['student_id'=>$sid,'academic_period_id'=>$p->id,'study_group_id'=>$ap->study_group_id,'starts_on'=>$d['effective_on'],'status'=>'active','created_at'=>now(),'updated_at'=>now()]);DB::table('student_movements')->insert(['student_id'=>$sid,'academic_period_id'=>$p->id,'type'=>'enrollment','to_group_id'=>$ap->study_group_id,'effective_on'=>$d['effective_on'],'academic_order_id'=>$order,'order_number'=>$d['order_number'],'order_date'=>$d['order_date'],'basis'=>$d['basis']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('admission_applications')->where('id',$ap->id)->update(['status'=>'enrolled','student_id'=>$sid,'updated_at'=>now()]);DB::table('admission_applications')->where('applicant_id',$ap->applicant_id)->where('id','<>',$ap->id)->whereNotIn('status',['enrolled','rejected'])->update(['status'=>'rejected','updated_at'=>now()]);}});return redirect()->route('academic.movements')->with('success','Зачисление оформлено приказом, студенты созданы');}
 public function update(Request $r,$id){abort(410,'Устаревшая операция. Изменяйте абитуриента и его заявления отдельно.');}
}